import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:secure_storage/src/core/param/param_secure_storage.dart';

/// {@template secure_storage}
/// Encrypted key-value storage backed by Hive CE boxes.
///
/// Each box may be AES encrypted. The encryption key is generated by Hive and
/// stored in the platform keystore through Flutter Secure Storage, under the
/// box name — so the key never touches the Hive file itself.
///
/// Every method throws an `AppException` subtype on failure. Prefer the
/// `StorageRepository` or the use cases if you would rather receive an
/// `Either<Failure, T>` than catch exceptions.
/// {@endtemplate}
abstract class SecureStorage {
  /// Reports whether an entry exists, and whether its box is encrypted.
  ///
  /// Returns `(exist: false, encrypted: null)` when the box itself does not
  /// exist yet — the `null` distinguishes "no box" from "box exists but has no
  /// such key", which is what [storeData] uses to decide whether it is
  /// creating a box or adding to one.
  Future<({bool exist, bool? encrypted})> isDataExist({
    required ParamCheckData param,
  });

  /// Writes [data] under `param.dataKey`.
  ///
  /// Creates the box on first use, honouring `param.encrypted`. For a box that
  /// already exists the existing encryption mode wins.
  Future<void> storeData<T>({required T data, required ParamStoreData param});

  /// Reads the entry addressed by [param].
  ///
  /// Throws `DataDoesNotExistException` if there is nothing stored there.
  Future<T?> getData<T>({required ParamGetData param});

  /// Deletes the entry addressed by [param].
  ///
  /// When this empties the box, the box is also deleted from disk and — if it
  /// was encrypted — its key is removed from the platform keystore.
  Future<void> deleteData<T>({required ParamDeleteData param});

  /// Returns every box key held in Flutter Secure Storage, as box name to
  /// base64url encoded encryption key.
  ///
  /// The values are live encryption keys. Do not log or transmit them.
  Future<Map<String, String>> listEncryptedKeys();

  /// Returns the names of the Hive boxes on disk that have no encryption key.
  ///
  /// Always returns an empty list on web, where boxes are not files.
  /// [directory] is a test seam and should be left unset in production.
  Future<List<dynamic>> listUnencryptedKeys({
    @visibleForTesting Directory? directory,
  });
}
